 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    # A separator is a full, uniform row or column in a non-background color.
    for axis, n, m in ((0, h, w), (1, w, h)):
        by_color = {}
        for i in range(n):
            line = [grid[i][j] for j in range(m)] if axis == 0 else [grid[j][i] for j in range(m)]
            if line and all(v == line[0] for v in line) and line[0] != bg:
                by_color.setdefault(line[0], []).append(i)
        for color, cuts in by_color.items():
            bounds = [-1] + cuts + [n]
            spans = [(bounds[k] + 1, bounds[k + 1]) for k in range(len(bounds) - 1)]
            lengths = [b-a for a,b in spans]
            if len(spans) > 1 and len(set(lengths)) == 1:
                # Prefer the axis/color with more repeated separators.
                candidates.append((len(cuts), axis, spans, color))
    if not candidates:
        return [row[:] for row in grid]
    _, axis, spans, _ = max(candidates, key=lambda x: x[0])
    def slab_score(span):
        a, b = span
        if axis == 0:
            vals = [grid[i][j] for i in range(a,b) for j in range(w)]
        else:
            vals = [grid[j][i] for i in range(a,b) for j in range(h)]
        return sum(v != bg for v in vals)
    src = max(spans, key=slab_score)
    out = [row[:] for row in grid]
    a0, b0 = src
    for a,b in spans:
        if (a,b) == src:
            continue
        for k in range(b-a):
            if axis == 0:
                out[a+k] = grid[a0+k][:]
            else:
                for r in range(h):
                    out[r][a+k] = grid[r][a0+k]
    return out
